) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_520_ci;

-- ------ Table: `expedient` ------
DROP TABLE IF EXISTS `expedient`;
CREATE TABLE `expedient` (
  `id` bigint NOT NULL,
  `id_client` bigint DEFAULT NULL,
  `id_order` bigint DEFAULT NULL,
  `id_customer_type` bigint DEFAULT NULL,
  `id_operation` bigint DEFAULT '0',
  `id_sale_type` bigint DEFAULT '0',
  `registration_date` timestamp NULL DEFAULT NULL,
  `update_date` timestamp NULL DEFAULT NULL,
  `id_agency` bigint DEFAULT NULL,
  `id_seller` bigint DEFAULT NULL,
  `id_last_user_update` bigint DEFAULT '0',
  `enabled` tinyint DEFAULT '1',
  `description` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci DEFAULT NULL,
  `id_current_expedient_state` int DEFAULT '0',
  `id_order_total` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci DEFAULT NULL,
  `attention_date` date DEFAULT NULL,
  `close_date` date DEFAULT NULL,
  `agend_hour` time DEFAULT NULL,
  `agend_date` date DEFAULT NULL,
  `id_inventory` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `WDIDX_File_IdClient` (`id_client`),
  KEY `WDIDX_File_IdOrder` (`id_order`),
  KEY `WDIDX_File_IdCustomerType` (`id_customer_type`),
  KEY `WDIDX_File_IdOperation` (`id_operation`),
  KEY `WDIDX_File_IdProcess` (`id_sale_type`),
  KEY `WDIDX_File_IdAgency` (`id_agency`),
  KEY `WDIDX_File_IdSeller` (`id_seller`),
  KEY `WDIDX_File_IdCurrentState` (`id_current_expedient_state`),
  KEY `WDIDX_File_IdOrderTotal` (`id_order_total`),
  KEY `WDIDX_File_IdInventary` (`id_inventory`),
  KEY `WDIDX_File_IdOrderTotalIdAgency` (`id_order_total`,`id_agency`),
  KEY `WDIDX_File_IdIdCurrentState` (`id`,`id_current_expedient_state`),
  KEY `IDX_File_RegistrationDate_IdAgency` (`registration_date`,`id_agency`),
  KEY `IDX_File_RegistrationDate_IdAgency_IdCurrentState` (`registration_date`,`id_agency`,`id_current_expedient_state`),
  KEY `IDX_File_RegistrationDate_idSeller` (`registration_date`,`id_seller`),
  KEY `IDX_File_RegistrationDate_IdAgency_idSeller` (`registration_date`,`id_agency`,`id_seller`),
  KEY `IDX_File_CloseDate` (`close_date`),
  KEY `IDX_File_RegistrationDate_CloseDate` (`registration_date`,`close_date`),
  KEY `IDX_File_Agency_State_Date` (`id_agency`,`id_current_expedient_state`,`registration_date` DESC),
  KEY `IDX_File_Client_Process` (`id_client`,`id_sale_type`),
  KEY `IDX_File_Client_Agency_State` (`id_client`,`id_agency`,`id_current_expedient_state`),
  KEY `IDX_File_OrderTotal` (`id_order_total`),
  KEY `IDX_File_Date_State` (`registration_date` DESC,`id_current_expedient_state`),
  KEY `FK_expedient_IdLastUserUpdate` (`id_last_user_update`),
  KEY `idx_expedient_RegistrationDate` (`registration_date` DESC),
  CONSTRAINT `expedient_ibfk_3` FOREIGN KEY (`id_operation`) REFERENCES `operation_type` (`id`),
  CONSTRAINT `expedient_ibfk_4` FOREIGN KEY (`id_customer_type`) REFERENCES `customer_type` (`id`),
  CONSTRAINT `expedient_ibfk_5` FOREIGN KEY (`id_sale_type`) REFERENCES `sale_type` (`id`),
  CONSTRAINT `expedient_ibfk_6` FOREIGN KEY (`id_agency`) REFERENCES `agency` (`id`),
  CONSTRAINT `expedient_ibfk_7` FOREIGN KEY (`id_seller`) REFERENCES `user` (`id`),
  CONSTRAINT `expedient_ibfk_8` FOREIGN KEY (`id_current_expedient_state`) REFERENCES `file_status` (`id`),
  CONSTRAINT `FK_expedient_IdClient` FOREIGN KEY (`id_client`) REFERENCES `client_header` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `FK_expedient_IdLastUserUpdate` FOREIGN KEY (`id_last_user_update`) REFERENCES `user` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `FK_expedient_IdOrder` FOREIGN KEY (`id_order`) REFERENCES `order` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `FK_File_CustomerType` FOREIGN KEY (`id_customer_type`) REFERENCES `customer_type` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_520_ci;

