-- ------ Table: `expedient_pld` ------
DROP TABLE IF EXISTS `expedient_pld`;
CREATE TABLE `expedient_pld` (
  `id` bigint NOT NULL,
  `id_expedient` bigint DEFAULT NULL,
  `privacy_notice_delivered` tinyint(1) DEFAULT '0' COMMENT '1=Yes, 0=No',
  `privacy_notice_date` datetime DEFAULT NULL COMMENT 'Delivery/acceptance date',
  `privacy_notice_method` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci DEFAULT NULL COMMENT 'In-person, Digital, Mail, Miniportal',
  `privacy_notice_signature` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci DEFAULT NULL COMMENT 'Path or reference to digital signature',
  `requires_beneficial_owner` tinyint(1) DEFAULT '0' COMMENT '1=Applies, 0=Not applicable',
  `beneficial_owner_captured` tinyint(1) DEFAULT '0' COMMENT '1=Yes, 0=Pending',
  `beneficial_owner_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci DEFAULT NULL,
  `beneficial_owner_rfc` varchar(13) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci DEFAULT NULL,
  `beneficial_owner_curp` varchar(18) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci DEFAULT NULL,
  `beneficial_owner_percentage` decimal(5,2) DEFAULT NULL COMMENT 'Participation percentage',
  `beneficial_owner_capture_date` datetime DEFAULT NULL,
  `funds_source_captured` tinyint(1) DEFAULT '0' COMMENT '1=Yes, 0=Pending',
  `funds_source_description` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci DEFAULT NULL COMMENT 'Description of funds origin',
  `funds_source_capture_date` datetime DEFAULT NULL,
  `identification_type` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci DEFAULT NULL COMMENT 'CIF, CSF or NULL if not applicable',
  `geolocation_captured` tinyint(1) DEFAULT '0' COMMENT '1=Yes, 0=No',
  `geolocation_latitude` decimal(10,8) DEFAULT NULL,
  `geolocation_longitude` decimal(11,8) DEFAULT NULL,
  `geolocation_date` datetime DEFAULT NULL,
  `geolocation_origin` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci DEFAULT NULL COMMENT 'Miniportal, App, Agency',
  `expedient_pld_complete` tinyint(1) DEFAULT '0' COMMENT '1=Complete, 0=Incomplete',
  `expedient_pld_complete_date` datetime DEFAULT NULL COMMENT 'When it was marked complete',
  `registration_date` datetime DEFAULT CURRENT_TIMESTAMP,
  `update_date` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `id_last_user_update` bigint DEFAULT NULL,
  `enabled` tinyint(1) DEFAULT '1',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_file_pld_idfile` (`id_expedient`),
  KEY `idx_file_pld_completo` (`expedient_pld_complete`),
  KEY `idx_file_pld_aviso` (`privacy_notice_delivered`),
  KEY `idx_file_pld_beneficiario` (`beneficial_owner_captured`),
  KEY `FK_file_pld_IdLastUserUpdate` (`id_last_user_update`),
  CONSTRAINT `FK_file_pld_IdFile` FOREIGN KEY (`id_expedient`) REFERENCES `expedient` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `FK_file_pld_IdLastUserUpdate` FOREIGN KEY (`id_last_user_update`) REFERENCES `user` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_520_ci COMMENT='Datos PLD/AML por expediente - Ley Antilavado';

-- ------ Table: `expedient_pld_approved_document` ------
