-- ====== Views ======

DROP VIEW IF EXISTS `view_client_company_amount`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY INVOKER VIEW `view_client_company_amount` AS select `c`.`id` AS `idCliente`,`a`.`id_company` AS `idCompany`,year(`f`.`registration_date`) AS `anio`,sum(coalesce(`obc1`.`amount`,`obc2`.`amount`,0)) AS `totalMonto` from ((((`expedient` `f` join `client` `c` on((`f`.`id_client` = `c`.`id`))) join `agency` `a` on((`f`.`id_agency` = `a`.`id`))) left join `order` `obc1` on((`obc1`.`id` = `f`.`id_order`))) left join (select `obc2a`.`id_dms` AS `id_dms`,`obc2a`.`id_agency` AS `id_agency`,`obc2a`.`amount` AS `amount` from (`order` `obc2a` join (select `order`.`id_dms` AS `id_dms`,`order`.`id_agency` AS `id_agency`,max(coalesce(`order`.`registration_date`,'1900-01-01')) AS `MaxDate` from `order` group by `order`.`id_dms`,`order`.`id_agency`) `obc2b` on(((`obc2a`.`id_dms` = `obc2b`.`id_dms`) and (`obc2a`.`id_agency` = `obc2b`.`id_agency`) and (coalesce(`obc2a`.`registration_date`,'1900-01-01') = `obc2b`.`MaxDate`))))) `obc2` on(((`f`.`id_order` is null) and (`obc2`.`id_dms` = `f`.`id_order_total`) and (`obc2`.`id_agency` = `f`.`id_agency`)))) group by `c`.`id`,`a`.`id_company`,year(`f`.`registration_date`) having (sum(coalesce(`obc1`.`amount`,`obc2`.`amount`,0)) > 0);

DROP VIEW IF EXISTS `view_client_company_amount_6m`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY INVOKER VIEW `view_client_company_amount_6m` AS select `c`.`id` AS `idCliente`,`a`.`id_company` AS `idCompany`,sum(coalesce(`lrd`.`amount`,0)) AS `totalMonto` from ((((`expedient` `f` join `client` `c` on((`f`.`id_client` = `c`.`id`))) join `agency` `a` on((`f`.`id_agency` = `a`.`id`))) join `liquidation_receipt_detail` `lrd` on(((`lrd`.`id_expedient` = `f`.`id`) and (`lrd`.`id_payment_method` = 1)))) join `expedient_document` `fd` on(((`fd`.`id` = `lrd`.`id_expedient_document`) and (`fd`.`enabled` = 1)))) where (coalesce(`lrd`.`payment_date`,cast(`lrd`.`registration_date` as date),cast(`f`.`registration_date` as date)) >= (curdate() - interval 6 month)) group by `c`.`id`,`a`.`id_company` having (sum(coalesce(`lrd`.`amount`,0)) > 0);

DROP VIEW IF EXISTS `view_client_company_amount_6m_total`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY INVOKER VIEW `view_client_company_amount_6m_total` AS select `c`.`id` AS `idCliente`,`a`.`id_company` AS `idCompany`,sum(coalesce(`lrd`.`amount`,0)) AS `totalMonto` from ((((`expedient` `f` join `client` `c` on((`f`.`id_client` = `c`.`id`))) join `agency` `a` on((`f`.`id_agency` = `a`.`id`))) join `liquidation_receipt_detail` `lrd` on((`lrd`.`id_expedient` = `f`.`id`))) join `expedient_document` `fd` on(((`fd`.`id` = `lrd`.`id_expedient_document`) and (`fd`.`enabled` = 1)))) where (coalesce(`lrd`.`payment_date`,cast(`lrd`.`registration_date` as date),cast(`f`.`registration_date` as date)) >= (curdate() - interval 6 month)) group by `c`.`id`,`a`.`id_company` having (sum(coalesce(`lrd`.`amount`,0)) > 0);

DROP VIEW IF EXISTS `view_client_relations`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY INVOKER VIEW `view_client_relations` AS select `hc`.`id_client` AS `idCliente`,coalesce(`ctr`.`id_dms`,'') AS `ndCliente`,trim(concat(coalesce(`c`.`name`,''),' ',coalesce(`c`.`last_name`,''),' ',coalesce(`c`.`mother_last_name`,''))) AS `cliente`,`hc`.`id` AS `IdClientHeader`,`c`.`name` AS `nombre`,`c`.`last_name` AS `apellidoPaterno`,`c`.`mother_last_name` AS `apellidoMaterno`,`c`.`RFC` AS `rfc`,`c`.`email` AS `email`,`c`.`tel_number` AS `telefono`,`c`.`tel_number2` AS `telefono2`,`c`.`business_name` AS `razonSocial`,`c`.`CURP` AS `curp`,`c`.`client_type` AS `tipoCliente`,`c`.`adviser` AS `asesor`,`c`.`agency_origin` AS `agenciaOrigen`,`c`.`registration_date` AS `fechaRegistro`,`c`.`update_date` AS `fechaActualizacion`,`ctr`.`id_agency` AS `id_agency` from ((`client_header` `hc` join `client_dms_relation` `ctr` on((`hc`.`id` = `ctr`.`id_client_header`))) join `client` `c` on((`c`.`id` = `hc`.`id_client`)));

DROP VIEW IF EXISTS `view_document_name`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY INVOKER VIEW `view_document_name` AS select `fd`.`id` AS `IdFileDocument`,`fd`.`id_expedient` AS `id_expedient`,coalesce(`dt`.`name`,`fd`.`name`) AS `file_name_original` from (`expedient_document` `fd` left join `document_type` `dt` on((`fd`.`id_document_type` = `dt`.`id`))) where (`fd`.`enabled` = 1);

SET FOREIGN_KEY_CHECKS = 1;
